// If the extension has set allowedSpaces to an empty array, the button needs
// to be added to all available spaces.
const allowedSpaces =
  this.allowedSpaces.length == 0
    ? [
        "mail",
        "addressbook",
        "calendar",
        "tasks",
        "chat",
        "settings",
        "default",
      ]
    : this.allowedSpaces;
